// One row per ranked app, with your own app flagged so the sheet reads as a
// leaderboard rather than a list. Play search returns apps in rank order, so
// position is the ranking for that keyword on that day.
const cfg = $('Set the keywords to track').first().json;
const yours = String(cfg.yourPackageName || '').trim().toLowerCase();
const weekOf = $now.toFormat('yyyy-MM-dd');

const clip = (s, n) => {
  const v = String(s || '').replace(/\s+/g, ' ').trim();
  return v.length > n ? v.slice(0, n - 3) + '...' : v;
};

return $input.all().map((item) => {
  const a = item.json;
  const pkg = String(a.productId || '');
  return {
    json: {
      'Week of': weekOf,
      Keyword: a.query || '',
      Rank: a.position ?? '',
      App: clip(a.title, 120),
      'Is your app': yours !== '' && pkg.toLowerCase() === yours ? 'YES' : '',
      Developer: clip(a.developer, 120),
      Category: a.category || '',
      Rating: typeof a.rating === 'number' ? a.rating : '',
      Downloads: a.downloads || '',
      'Package name': pkg,
      'Play listing': a.url || '',
    },
  };
});
